// คำนวณช่วง "เมื่อวาน" ตามเวลาไทย (Asia/Bangkok = UTC+7 ไม่มี DST)
const dstr = (offsetDays) => new Date(Date.now() + 7 * 3600 * 1000 + offsetDays * 86400000)
  .toISOString().slice(0, 10);
return [{ json: { gte: dstr(-1), lt: dstr(0) } }]; // เช่น gte=2026-07-01, lt=2026-07-02

function bubble(title, body, btnLabel, uri, extra) {
  const bodyContents = [
    { type: 'text', text: title, weight: 'bold', size: 'md', wrap: true, color: '#1F2A22' },
    { type: 'text', text: body, size: 'sm', color: '#6B7A6E', wrap: true }
  ];
  if (extra) bodyContents.push({ type: 'text', text: extra, size: 'xs', color: '#8A9388', wrap: true, margin: 'md' });
  return {
    type: 'bubble',
    header: { type: 'box', layout: 'vertical', backgroundColor: '#3E5C46', paddingAll: '16px',
      contents: [ { type: 'text', text: 'LLOOP', color: '#FFFFFF', weight: 'bold', size: 'sm' } ] },
    body: { type: 'box', layout: 'vertical', spacing: 'sm', paddingAll: '20px', contents: bodyContents },
    footer: { type: 'box', layout: 'vertical', paddingAll: '16px',
      contents: [ { type: 'button', style: 'primary', color: '#3E5C46', height: 'sm',
        action: { type: 'uri', label: btnLabel, uri: uri } } ] }
  };
}

// รวมให้เหลือ 1 ข้อความต่อลูกค้า 1 คน — คืนหลายชุดเมื่อวานก็ทักครั้งเดียวพอค่ะ
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const uid = item.json.line_uid;
  if (!uid || seen.has(uid)) continue;
  seen.add(uid);
  const title = 'ชุดล่าสุดใส่เป็นยังไงคะ';
  const bodyText = 'บอกเราสั้น ๆ แค่ 20 วิ โปรไฟล์ความพอดีของคุณจะแม่นขึ้นค่ะ';
  const contents = bubble(title, bodyText, 'บอกความพอดี (20 วิ)',
                          'https://wearlloop-dotcom.github.io/fit.html');
  out.push({ json: { lineBody: { to: uid, messages: [{ type: 'flex',
    altText: 'ชุดล่าสุดใส่เป็นยังไงคะ บอก 20 วิ โปรไฟล์จะแม่นขึ้นค่ะ', contents }] } } });
}
return out;
